if (!$json.active_draft_id) throw new Error('active_draft_id is required');
if ($json.conversation_state !== 'AWAITING_APPROVAL') throw new Error('draft revision requires AWAITING_APPROVAL');
return [{ json: $json }];

const draft = $json.active_draft || $json;
const patches = $json.patches || $json.patch?.patches || [];

if (!Array.isArray(patches) || patches.length === 0) {
  throw new Error('at least one patch is required');
}
if (!Array.isArray(draft.items) || draft.items.length === 0) {
  throw new Error('active draft items are required');
}

const updated = {
  ...draft,
  items: draft.items.map((item) => ({ ...item })),
};

for (const operation of patches) {
  if (operation.target === 'item:return_trip') {
    const item = updated.items[updated.items.length - 1];
    applyItemPatch(item, operation.field, operation.value);
  } else if (operation.target === 'draft') {
    applyDraftPatch(updated, operation.field, operation.value);
  } else {
    throw new Error(`unsupported patch target: ${operation.target}`);
  }
}

return [{ json: { ...$json, ...updated, revision_applied: true } }];

function applyItemPatch(item, field, value) {
  if (!['trip_date', 'unit_price'].includes(field)) {
    throw new Error(`unsupported item patch field: ${field}`);
  }
  if (field === 'unit_price') {
    const numericValue = Number(value);
    if (!Number.isInteger(numericValue) || numericValue < 0) {
      throw new Error('unit_price patch must be a non-negative integer');
    }
    item.unit_price = numericValue;
    return;
  }
  item[field] = value;
}

function applyDraftPatch(draft, field, value) {
  if (!['payment_type', 'down_payment_amount'].includes(field)) {
    throw new Error(`unsupported draft patch field: ${field}`);
  }
  if (field === 'payment_type') {
    draft.payment_type = String(value).trim().toUpperCase();
    return;
  }
  const numericValue = Number(value);
  if (!Number.isInteger(numericValue) || numericValue < 0) {
    throw new Error('down_payment_amount patch must be a non-negative integer');
  }
  draft.down_payment_amount = numericValue;
}

const items = $json.items || [];
const discount = Number($json.discount || 0);
const additionalFee = Number($json.additional_fee || 0);
const paymentType = String($json.payment_type || $json.payment?.type || 'UNSPECIFIED').trim().toUpperCase();
const downPaymentAmount = Number($json.down_payment_amount || $json.payment?.down_payment_amount || 0);

if (discount < 0 || additionalFee < 0 || downPaymentAmount < 0) {
  throw new Error('discount, additional_fee, and down_payment_amount must be non-negative');
}

let subtotal = 0;
const calculatedItems = items.map((item, index) => {
  const quantity = Number(item.quantity);
  const unitPrice = Number(item.unit_price);
  if (!Number.isInteger(quantity) || quantity <= 0) {
    throw new Error(`item ${index + 1} quantity must be a positive integer`);
  }
  if (!Number.isInteger(unitPrice) || unitPrice < 0) {
    throw new Error(`item ${index + 1} unit_price must be a non-negative integer`);
  }
  const lineTotal = quantity * unitPrice;
  subtotal += lineTotal;
  return {
    ...item,
    sort_order: index + 1,
    quantity,
    unit_price: unitPrice,
    line_total: lineTotal,
  };
});

const grandTotal = subtotal - discount + additionalFee;
if (grandTotal < 0) {
  throw new Error('grand_total must be non-negative');
}
const effectiveDownPayment = paymentType === 'FULL_PAYMENT' ? 0 : downPaymentAmount;
if (effectiveDownPayment > grandTotal) {
  throw new Error('down_payment_amount must not exceed grand_total');
}

const balanceDue = paymentType === 'FULL_PAYMENT' ? 0 : grandTotal - effectiveDownPayment;

return [
  {
    json: {
      ...$json,
      items: calculatedItems,
      payment_type: paymentType,
      subtotal,
      discount,
      additional_fee: additionalFee,
      grand_total: grandTotal,
      down_payment_amount: effectiveDownPayment,
      balance_due: balanceDue,
    },
  },
];

const crypto = require('crypto');

function normalizeText(value) {
  if (value === null || value === undefined) return null;
  return String(value).normalize('NFKC').trim().toLowerCase().replace(/\s+/g, ' ');
}

function canonicalInt(value) {
  if (value === null || value === undefined || value === '') return 0;
  const normalized = String(value).trim().toLowerCase().replace(/\s+/g, '');
  if (normalized.includes('juta')) {
    const amount = normalized.replace('rp', '').replace('juta', '').replace(',', '.');
    return Math.round(Number.parseFloat(amount) * 1000000);
  }
  return Number.parseInt(normalized.replace(/[^\d-]/g, ''), 10);
}

const canonical = {
  customer: normalizeText($json.customer_name || $json.customer?.name),
  payment_type: String($json.payment_type || $json.payment?.type || '').trim().toUpperCase(),
  down_payment_amount: canonicalInt($json.down_payment_amount || $json.payment?.down_payment_amount || 0),
  discount: canonicalInt($json.discount || 0),
  additional_fee: canonicalInt($json.additional_fee || 0),
  items: ($json.items || []).map((item) => ({
    trip_date: item.trip_date || null,
    vehicle_type: normalizeText(item.vehicle_type),
    quantity: canonicalInt(item.quantity),
    pickup: normalizeText(item.pickup),
    destination: normalizeText(item.destination),
    unit_price: canonicalInt(item.unit_price),
  })).sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b))),
};

const payload = JSON.stringify(canonical);
const contentFingerprint = crypto.createHash('sha256').update(payload).digest('hex');

return [{ json: { ...$json, canonical_business_data: canonical, content_fingerprint: contentFingerprint } }];

function rupiah(amount) {
  return 'Rp' + Number(amount || 0).toLocaleString('id-ID');
}

function formatDate(value) {
  if (!value) return '-';
  return new Intl.DateTimeFormat('id-ID', { day: 'numeric', month: 'long', year: 'numeric' }).format(new Date(value));
}

const lines = [
  '📄 PRATINJAU INVOICE',
  '',
  'Kepada:',
  $json.customer_name,
  '',
];

for (const item of $json.items || []) {
  lines.push(formatDate(item.trip_date));
  lines.push(`${item.vehicle_type}`);
  lines.push(`${item.quantity} unit × ${rupiah(item.unit_price)}`);
  lines.push(`= ${rupiah(item.line_total)}`);
  lines.push(`${item.pickup || '-'} → ${item.destination || '-'}`);
  lines.push('');
}

lines.push('TOTAL');
lines.push(rupiah($json.grand_total));
lines.push('');
lines.push('Pembayaran:');
lines.push($json.payment_type === 'FULL_PAYMENT' ? 'LUNAS / FULL PAYMENT' : $json.payment_type);
if ($json.down_payment_amount) {
  lines.push(`DP: ${rupiah($json.down_payment_amount)}`);
}
if ($json.balance_due) {
  lines.push(`Sisa pembayaran: ${rupiah($json.balance_due)}`);
}

if (($json.included || []).length) {
  lines.push('');
  lines.push('Termasuk:');
  for (const item of $json.included) lines.push(`✓ ${item}`);
}

if (($json.excluded || []).length) {
  lines.push('');
  lines.push('Tidak termasuk:');
  for (const item of $json.excluded) lines.push(`- ${item}`);
}

lines.push('');
lines.push('Sudah benar?');
lines.push('Balas: setuju atau tulis revisinya.');

return [{ json: { ...$json, preview_text: lines.join('\n') } }];
